with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'المناخ الحضري والجزيرة الحرارية والتكيف','الجزيرة الحرارية وميزانية الطاقة الحضرية وهندسة الشوارع والتهوية والرصد الحراري وجودة الهواء واستراتيجيات التكيف.',61,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'فيزياء المناخ الحضري والميزانية السطحية',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الرصد والتقييم والتكيف الحضري',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit_title) as (values
('urban-canopy-layer','طبقة الغطاء الحضري','تبادل الطاقة والهواء بين المباني','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تمثل طبقة الغطاء الحضري الحيز الواقع بين سطح الأرض ومستويات أسطح المباني، وتتأثر بهندسة الشوارع ومواد البناء والظل والتهوية ومصادر الحرارة البشرية."},{"type":"heading","text":"الآلية المناخية"},{"type":"text","text":"يتشكل المناخ الحضري من تفاعل الغلاف الجوي مع هندسة المباني وخصائص المواد والغطاء النباتي والماء ومصادر الحرارة البشرية. ويجب فصل حرارة السطح عن حرارة الهواء، والتمييز بين مقياس الشارع والحي والمدينة عند تفسير النتائج."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["حرارة الهواء والسطح والرطوبة والرياح والإشعاع.","خصائص مواد السطح والغطاء الأرضي وارتفاعات المباني.","مواقع المحطات وارتفاع المجسات وظروف التعرض.","صور حرارية وخرائط عمرانية وبيانات سكانية مناسبة.","سلاسل زمنية تشمل النهار والليل ومواسم مختلفة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد النطاق الحضري والمقياس المكاني والهدف.","صنف الأسطح والأنماط العمرانية ومواقع الرصد.","حلل المتغيرات الجوية والسطحية معاً.","قارن المواقع الحضرية بمرجع مناسب مع ضبط الارتفاع والتوقيت.","قيم التدخلات بمؤشرات قابلة للقياس واذكر القيود."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"طبقة الغطاء الحضري","text":"قارن مقطع شارع ضيق وآخر مفتوح من حيث التهوية والتخزين الحراري. استخدم سيناريو افتراضياً واضحاً، وبيّن الفرق بين القياس المرصود والاستنتاج المكاني."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن مقطع شارع ضيق وآخر مفتوح من حيث التهوية والتخزين الحراري."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار حرارة السطح مساوية لحرارة الهواء.","مقارنة محطات مختلفة التعرض أو الارتفاع دون ضبط.","تعميم قياس نقطة على كامل النسيج العمراني.","إغفال أثر الرطوبة والرياح والإشعاع في الإجهاد الحراري.","الحكم على تدخل دون خط أساس أو متابعة زمنية."]},{"type":"callout","text":"التقييم الحضري السليم يجمع بين القياسات الجوية وخصائص السطح والهندسة العمرانية والتعرض البشري، مع مراعاة اختلاف المقياس المكاني."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد علم المناخ الحضري على تفسير الفروق المحلية في الحرارة والتهوية وجودة الهواء، وتحويل الرصد المكاني إلى تدخلات تكيف قابلة للتقييم والتحسين."}]}'::jsonb,8360,55,'["شرح التفاعلات المناخية بين الغلاف الجوي والبيئة العمرانية","تحديد البيانات والمنهجيات المناسبة للرصد والتحليل الحضري","تقييم مخاطر الحرارة وخيارات التكيف على أسس علمية"]'::jsonb,'فيزياء المناخ الحضري والميزانية السطحية'),
('urban-heat-island-energy-balance','ميزانية الطاقة في الجزيرة الحرارية','الإشعاع والتخزين والتدفقات المحسوسة والكامنة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تنشأ الفروق الحرارية الحضرية من تغير ميزانية الطاقة السطحية، بما يشمل الإشعاع الصافي والحرارة المخزنة والتدفق الحراري المحسوس والكامن والحرارة البشرية."},{"type":"heading","text":"الآلية المناخية"},{"type":"text","text":"يتشكل المناخ الحضري من تفاعل الغلاف الجوي مع هندسة المباني وخصائص المواد والغطاء النباتي والماء ومصادر الحرارة البشرية. ويجب فصل حرارة السطح عن حرارة الهواء، والتمييز بين مقياس الشارع والحي والمدينة عند تفسير النتائج."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["حرارة الهواء والسطح والرطوبة والرياح والإشعاع.","خصائص مواد السطح والغطاء الأرضي وارتفاعات المباني.","مواقع المحطات وارتفاع المجسات وظروف التعرض.","صور حرارية وخرائط عمرانية وبيانات سكانية مناسبة.","سلاسل زمنية تشمل النهار والليل ومواسم مختلفة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد النطاق الحضري والمقياس المكاني والهدف.","صنف الأسطح والأنماط العمرانية ومواقع الرصد.","حلل المتغيرات الجوية والسطحية معاً.","قارن المواقع الحضرية بمرجع مناسب مع ضبط الارتفاع والتوقيت.","قيم التدخلات بمؤشرات قابلة للقياس واذكر القيود."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"ميزانية الطاقة في الجزيرة الحرارية","text":"حلل كيف يغير انخفاض المساحات الخضراء توزيع التدفقات الحرارية. استخدم سيناريو افتراضياً واضحاً، وبيّن الفرق بين القياس المرصود والاستنتاج المكاني."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل كيف يغير انخفاض المساحات الخضراء توزيع التدفقات الحرارية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار حرارة السطح مساوية لحرارة الهواء.","مقارنة محطات مختلفة التعرض أو الارتفاع دون ضبط.","تعميم قياس نقطة على كامل النسيج العمراني.","إغفال أثر الرطوبة والرياح والإشعاع في الإجهاد الحراري.","الحكم على تدخل دون خط أساس أو متابعة زمنية."]},{"type":"callout","text":"التقييم الحضري السليم يجمع بين القياسات الجوية وخصائص السطح والهندسة العمرانية والتعرض البشري، مع مراعاة اختلاف المقياس المكاني."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد علم المناخ الحضري على تفسير الفروق المحلية في الحرارة والتهوية وجودة الهواء، وتحويل الرصد المكاني إلى تدخلات تكيف قابلة للتقييم والتحسين."}]}'::jsonb,8370,55,'["شرح التفاعلات المناخية بين الغلاف الجوي والبيئة العمرانية","تحديد البيانات والمنهجيات المناسبة للرصد والتحليل الحضري","تقييم مخاطر الحرارة وخيارات التكيف على أسس علمية"]'::jsonb,'فيزياء المناخ الحضري والميزانية السطحية'),
('urban-rural-temperature-contrast','قياس الفرق الحراري بين المدينة والريف','اختيار المحطات والتوقيت والمرجع','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يعتمد قياس الجزيرة الحرارية على مقارنة مواقع حضرية وريفية متقاربة مناخياً مع ضبط الارتفاع والتعرض والتوقيت ونوع السطح. يتغير الفرق بين الليل والنهار والفصول."},{"type":"heading","text":"الآلية المناخية"},{"type":"text","text":"يتشكل المناخ الحضري من تفاعل الغلاف الجوي مع هندسة المباني وخصائص المواد والغطاء النباتي والماء ومصادر الحرارة البشرية. ويجب فصل حرارة السطح عن حرارة الهواء، والتمييز بين مقياس الشارع والحي والمدينة عند تفسير النتائج."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["حرارة الهواء والسطح والرطوبة والرياح والإشعاع.","خصائص مواد السطح والغطاء الأرضي وارتفاعات المباني.","مواقع المحطات وارتفاع المجسات وظروف التعرض.","صور حرارية وخرائط عمرانية وبيانات سكانية مناسبة.","سلاسل زمنية تشمل النهار والليل ومواسم مختلفة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد النطاق الحضري والمقياس المكاني والهدف.","صنف الأسطح والأنماط العمرانية ومواقع الرصد.","حلل المتغيرات الجوية والسطحية معاً.","قارن المواقع الحضرية بمرجع مناسب مع ضبط الارتفاع والتوقيت.","قيم التدخلات بمؤشرات قابلة للقياس واذكر القيود."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"قياس الفرق الحراري بين المدينة والريف","text":"ضع بروتوكول مقارنة يحد من تحيز اختيار المحطات. استخدم سيناريو افتراضياً واضحاً، وبيّن الفرق بين القياس المرصود والاستنتاج المكاني."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ضع بروتوكول مقارنة يحد من تحيز اختيار المحطات."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار حرارة السطح مساوية لحرارة الهواء.","مقارنة محطات مختلفة التعرض أو الارتفاع دون ضبط.","تعميم قياس نقطة على كامل النسيج العمراني.","إغفال أثر الرطوبة والرياح والإشعاع في الإجهاد الحراري.","الحكم على تدخل دون خط أساس أو متابعة زمنية."]},{"type":"callout","text":"التقييم الحضري السليم يجمع بين القياسات الجوية وخصائص السطح والهندسة العمرانية والتعرض البشري، مع مراعاة اختلاف المقياس المكاني."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد علم المناخ الحضري على تفسير الفروق المحلية في الحرارة والتهوية وجودة الهواء، وتحويل الرصد المكاني إلى تدخلات تكيف قابلة للتقييم والتحسين."}]}'::jsonb,8380,55,'["شرح التفاعلات المناخية بين الغلاف الجوي والبيئة العمرانية","تحديد البيانات والمنهجيات المناسبة للرصد والتحليل الحضري","تقييم مخاطر الحرارة وخيارات التكيف على أسس علمية"]'::jsonb,'فيزياء المناخ الحضري والميزانية السطحية'),
('urban-sky-view-factor','معامل رؤية السماء في المدن','هندسة الشوارع والإشعاع طويل الموجة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يصف معامل رؤية السماء الجزء المرئي من قبة السماء من نقطة ما، ويتحكم في تبادل الإشعاع طويل الموجة والتهوية المحلية. يتغير مع ارتفاع المباني وعرض الشوارع واتجاهها."},{"type":"heading","text":"الآلية المناخية"},{"type":"text","text":"يتشكل المناخ الحضري من تفاعل الغلاف الجوي مع هندسة المباني وخصائص المواد والغطاء النباتي والماء ومصادر الحرارة البشرية. ويجب فصل حرارة السطح عن حرارة الهواء، والتمييز بين مقياس الشارع والحي والمدينة عند تفسير النتائج."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["حرارة الهواء والسطح والرطوبة والرياح والإشعاع.","خصائص مواد السطح والغطاء الأرضي وارتفاعات المباني.","مواقع المحطات وارتفاع المجسات وظروف التعرض.","صور حرارية وخرائط عمرانية وبيانات سكانية مناسبة.","سلاسل زمنية تشمل النهار والليل ومواسم مختلفة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد النطاق الحضري والمقياس المكاني والهدف.","صنف الأسطح والأنماط العمرانية ومواقع الرصد.","حلل المتغيرات الجوية والسطحية معاً.","قارن المواقع الحضرية بمرجع مناسب مع ضبط الارتفاع والتوقيت.","قيم التدخلات بمؤشرات قابلة للقياس واذكر القيود."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"معامل رؤية السماء في المدن","text":"فسر لماذا قد تحتفظ الشوارع العميقة بالحرارة ليلاً أكثر من المواقع المفتوحة. استخدم سيناريو افتراضياً واضحاً، وبيّن الفرق بين القياس المرصود والاستنتاج المكاني."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر لماذا قد تحتفظ الشوارع العميقة بالحرارة ليلاً أكثر من المواقع المفتوحة."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار حرارة السطح مساوية لحرارة الهواء.","مقارنة محطات مختلفة التعرض أو الارتفاع دون ضبط.","تعميم قياس نقطة على كامل النسيج العمراني.","إغفال أثر الرطوبة والرياح والإشعاع في الإجهاد الحراري.","الحكم على تدخل دون خط أساس أو متابعة زمنية."]},{"type":"callout","text":"التقييم الحضري السليم يجمع بين القياسات الجوية وخصائص السطح والهندسة العمرانية والتعرض البشري، مع مراعاة اختلاف المقياس المكاني."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد علم المناخ الحضري على تفسير الفروق المحلية في الحرارة والتهوية وجودة الهواء، وتحويل الرصد المكاني إلى تدخلات تكيف قابلة للتقييم والتحسين."}]}'::jsonb,8390,55,'["شرح التفاعلات المناخية بين الغلاف الجوي والبيئة العمرانية","تحديد البيانات والمنهجيات المناسبة للرصد والتحليل الحضري","تقييم مخاطر الحرارة وخيارات التكيف على أسس علمية"]'::jsonb,'فيزياء المناخ الحضري والميزانية السطحية'),
('urban-materials-thermal-properties','الخصائص الحرارية لمواد البناء','السعة الحرارية والموصلية والانعكاس','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تحدد السعة الحرارية والموصلية والانعكاسية والانبعاثية طريقة امتصاص الطاقة وتخزينها وإطلاقها من الأسطح الحضرية. تختلف استجابة الأسفلت والخرسانة والمواد الفاتحة والغطاء النباتي."},{"type":"heading","text":"الآلية المناخية"},{"type":"text","text":"يتشكل المناخ الحضري من تفاعل الغلاف الجوي مع هندسة المباني وخصائص المواد والغطاء النباتي والماء ومصادر الحرارة البشرية. ويجب فصل حرارة السطح عن حرارة الهواء، والتمييز بين مقياس الشارع والحي والمدينة عند تفسير النتائج."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["حرارة الهواء والسطح والرطوبة والرياح والإشعاع.","خصائص مواد السطح والغطاء الأرضي وارتفاعات المباني.","مواقع المحطات وارتفاع المجسات وظروف التعرض.","صور حرارية وخرائط عمرانية وبيانات سكانية مناسبة.","سلاسل زمنية تشمل النهار والليل ومواسم مختلفة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد النطاق الحضري والمقياس المكاني والهدف.","صنف الأسطح والأنماط العمرانية ومواقع الرصد.","حلل المتغيرات الجوية والسطحية معاً.","قارن المواقع الحضرية بمرجع مناسب مع ضبط الارتفاع والتوقيت.","قيم التدخلات بمؤشرات قابلة للقياس واذكر القيود."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الخصائص الحرارية لمواد البناء","text":"قارن الاستجابة الحرارية اليومية لمادتين مختلفتين. استخدم سيناريو افتراضياً واضحاً، وبيّن الفرق بين القياس المرصود والاستنتاج المكاني."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن الاستجابة الحرارية اليومية لمادتين مختلفتين."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار حرارة السطح مساوية لحرارة الهواء.","مقارنة محطات مختلفة التعرض أو الارتفاع دون ضبط.","تعميم قياس نقطة على كامل النسيج العمراني.","إغفال أثر الرطوبة والرياح والإشعاع في الإجهاد الحراري.","الحكم على تدخل دون خط أساس أو متابعة زمنية."]},{"type":"callout","text":"التقييم الحضري السليم يجمع بين القياسات الجوية وخصائص السطح والهندسة العمرانية والتعرض البشري، مع مراعاة اختلاف المقياس المكاني."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد علم المناخ الحضري على تفسير الفروق المحلية في الحرارة والتهوية وجودة الهواء، وتحويل الرصد المكاني إلى تدخلات تكيف قابلة للتقييم والتحسين."}]}'::jsonb,8400,55,'["شرح التفاعلات المناخية بين الغلاف الجوي والبيئة العمرانية","تحديد البيانات والمنهجيات المناسبة للرصد والتحليل الحضري","تقييم مخاطر الحرارة وخيارات التكيف على أسس علمية"]'::jsonb,'فيزياء المناخ الحضري والميزانية السطحية'),
('urban-surface-albedo','البياض السطحي في البيئة الحضرية','انعكاس الإشعاع الشمسي وتباين الأسطح','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يؤثر البياض في نسبة الإشعاع الشمسي المنعكس، لكنه ليس العامل الوحيد في حرارة السطح؛ فالتظليل والتخزين الحراري والتهوية والرطوبة تؤثر أيضاً."},{"type":"heading","text":"الآلية المناخية"},{"type":"text","text":"يتشكل المناخ الحضري من تفاعل الغلاف الجوي مع هندسة المباني وخصائص المواد والغطاء النباتي والماء ومصادر الحرارة البشرية. ويجب فصل حرارة السطح عن حرارة الهواء، والتمييز بين مقياس الشارع والحي والمدينة عند تفسير النتائج."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["حرارة الهواء والسطح والرطوبة والرياح والإشعاع.","خصائص مواد السطح والغطاء الأرضي وارتفاعات المباني.","مواقع المحطات وارتفاع المجسات وظروف التعرض.","صور حرارية وخرائط عمرانية وبيانات سكانية مناسبة.","سلاسل زمنية تشمل النهار والليل ومواسم مختلفة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد النطاق الحضري والمقياس المكاني والهدف.","صنف الأسطح والأنماط العمرانية ومواقع الرصد.","حلل المتغيرات الجوية والسطحية معاً.","قارن المواقع الحضرية بمرجع مناسب مع ضبط الارتفاع والتوقيت.","قيم التدخلات بمؤشرات قابلة للقياس واذكر القيود."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"البياض السطحي في البيئة الحضرية","text":"ناقش حدود استخدام البياض وحده لتقييم تدخل تخفيف الحرارة. استخدم سيناريو افتراضياً واضحاً، وبيّن الفرق بين القياس المرصود والاستنتاج المكاني."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ناقش حدود استخدام البياض وحده لتقييم تدخل تخفيف الحرارة."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار حرارة السطح مساوية لحرارة الهواء.","مقارنة محطات مختلفة التعرض أو الارتفاع دون ضبط.","تعميم قياس نقطة على كامل النسيج العمراني.","إغفال أثر الرطوبة والرياح والإشعاع في الإجهاد الحراري.","الحكم على تدخل دون خط أساس أو متابعة زمنية."]},{"type":"callout","text":"التقييم الحضري السليم يجمع بين القياسات الجوية وخصائص السطح والهندسة العمرانية والتعرض البشري، مع مراعاة اختلاف المقياس المكاني."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد علم المناخ الحضري على تفسير الفروق المحلية في الحرارة والتهوية وجودة الهواء، وتحويل الرصد المكاني إلى تدخلات تكيف قابلة للتقييم والتحسين."}]}'::jsonb,8410,55,'["شرح التفاعلات المناخية بين الغلاف الجوي والبيئة العمرانية","تحديد البيانات والمنهجيات المناسبة للرصد والتحليل الحضري","تقييم مخاطر الحرارة وخيارات التكيف على أسس علمية"]'::jsonb,'فيزياء المناخ الحضري والميزانية السطحية'),
('urban-roughness-and-ventilation','خشونة المدينة والتهوية','المباني والقص والدوامات الحضرية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تغير المباني خشونة السطح وتولد مناطق انفصال ودوامات وقنوات تسريع للرياح. تؤثر هندسة الكتل واتجاه الشوارع وتوزيع الارتفاعات في تبادل الهواء والملوثات والحرارة."},{"type":"heading","text":"الآلية المناخية"},{"type":"text","text":"يتشكل المناخ الحضري من تفاعل الغلاف الجوي مع هندسة المباني وخصائص المواد والغطاء النباتي والماء ومصادر الحرارة البشرية. ويجب فصل حرارة السطح عن حرارة الهواء، والتمييز بين مقياس الشارع والحي والمدينة عند تفسير النتائج."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["حرارة الهواء والسطح والرطوبة والرياح والإشعاع.","خصائص مواد السطح والغطاء الأرضي وارتفاعات المباني.","مواقع المحطات وارتفاع المجسات وظروف التعرض.","صور حرارية وخرائط عمرانية وبيانات سكانية مناسبة.","سلاسل زمنية تشمل النهار والليل ومواسم مختلفة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد النطاق الحضري والمقياس المكاني والهدف.","صنف الأسطح والأنماط العمرانية ومواقع الرصد.","حلل المتغيرات الجوية والسطحية معاً.","قارن المواقع الحضرية بمرجع مناسب مع ضبط الارتفاع والتوقيت.","قيم التدخلات بمؤشرات قابلة للقياس واذكر القيود."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"خشونة المدينة والتهوية","text":"فسر كيف يغير انتظام المباني أو تفاوت ارتفاعها نمط التهوية. استخدم سيناريو افتراضياً واضحاً، وبيّن الفرق بين القياس المرصود والاستنتاج المكاني."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر كيف يغير انتظام المباني أو تفاوت ارتفاعها نمط التهوية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار حرارة السطح مساوية لحرارة الهواء.","مقارنة محطات مختلفة التعرض أو الارتفاع دون ضبط.","تعميم قياس نقطة على كامل النسيج العمراني.","إغفال أثر الرطوبة والرياح والإشعاع في الإجهاد الحراري.","الحكم على تدخل دون خط أساس أو متابعة زمنية."]},{"type":"callout","text":"التقييم الحضري السليم يجمع بين القياسات الجوية وخصائص السطح والهندسة العمرانية والتعرض البشري، مع مراعاة اختلاف المقياس المكاني."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد علم المناخ الحضري على تفسير الفروق المحلية في الحرارة والتهوية وجودة الهواء، وتحويل الرصد المكاني إلى تدخلات تكيف قابلة للتقييم والتحسين."}]}'::jsonb,8420,55,'["شرح التفاعلات المناخية بين الغلاف الجوي والبيئة العمرانية","تحديد البيانات والمنهجيات المناسبة للرصد والتحليل الحضري","تقييم مخاطر الحرارة وخيارات التكيف على أسس علمية"]'::jsonb,'فيزياء المناخ الحضري والميزانية السطحية'),
('urban-heat-storage-release','التخزين الحراري والإطلاق الليلي','القصور الحراري والتأخر اليومي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تمتص الكتل الحضرية الطاقة خلال النهار وتطلق جزءاً منها لاحقاً، ما يغير توقيت الذروة الحرارية ويحد من التبريد الليلي. تتباين الاستجابة بحسب المادة والهندسة والتعرض."},{"type":"heading","text":"الآلية المناخية"},{"type":"text","text":"يتشكل المناخ الحضري من تفاعل الغلاف الجوي مع هندسة المباني وخصائص المواد والغطاء النباتي والماء ومصادر الحرارة البشرية. ويجب فصل حرارة السطح عن حرارة الهواء، والتمييز بين مقياس الشارع والحي والمدينة عند تفسير النتائج."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["حرارة الهواء والسطح والرطوبة والرياح والإشعاع.","خصائص مواد السطح والغطاء الأرضي وارتفاعات المباني.","مواقع المحطات وارتفاع المجسات وظروف التعرض.","صور حرارية وخرائط عمرانية وبيانات سكانية مناسبة.","سلاسل زمنية تشمل النهار والليل ومواسم مختلفة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد النطاق الحضري والمقياس المكاني والهدف.","صنف الأسطح والأنماط العمرانية ومواقع الرصد.","حلل المتغيرات الجوية والسطحية معاً.","قارن المواقع الحضرية بمرجع مناسب مع ضبط الارتفاع والتوقيت.","قيم التدخلات بمؤشرات قابلة للقياس واذكر القيود."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"التخزين الحراري والإطلاق الليلي","text":"قارن توقيت حرارة الهواء والسطح في موقع حضري كثيف وموقع مفتوح. استخدم سيناريو افتراضياً واضحاً، وبيّن الفرق بين القياس المرصود والاستنتاج المكاني."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن توقيت حرارة الهواء والسطح في موقع حضري كثيف وموقع مفتوح."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار حرارة السطح مساوية لحرارة الهواء.","مقارنة محطات مختلفة التعرض أو الارتفاع دون ضبط.","تعميم قياس نقطة على كامل النسيج العمراني.","إغفال أثر الرطوبة والرياح والإشعاع في الإجهاد الحراري.","الحكم على تدخل دون خط أساس أو متابعة زمنية."]},{"type":"callout","text":"التقييم الحضري السليم يجمع بين القياسات الجوية وخصائص السطح والهندسة العمرانية والتعرض البشري، مع مراعاة اختلاف المقياس المكاني."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد علم المناخ الحضري على تفسير الفروق المحلية في الحرارة والتهوية وجودة الهواء، وتحويل الرصد المكاني إلى تدخلات تكيف قابلة للتقييم والتحسين."}]}'::jsonb,8430,55,'["شرح التفاعلات المناخية بين الغلاف الجوي والبيئة العمرانية","تحديد البيانات والمنهجيات المناسبة للرصد والتحليل الحضري","تقييم مخاطر الحرارة وخيارات التكيف على أسس علمية"]'::jsonb,'فيزياء المناخ الحضري والميزانية السطحية'),
('urban-green-infrastructure','البنية الخضراء الحضرية','التظليل والتبخر والنتح','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تخفض الأشجار والحدائق الحرارة عبر التظليل وتحويل جزء من الطاقة إلى تبخر ونتح، لكن كفاءتها تعتمد على توفر الماء ونوع النبات والغطاء والموقع والتهوية."},{"type":"heading","text":"الآلية المناخية"},{"type":"text","text":"يتشكل المناخ الحضري من تفاعل الغلاف الجوي مع هندسة المباني وخصائص المواد والغطاء النباتي والماء ومصادر الحرارة البشرية. ويجب فصل حرارة السطح عن حرارة الهواء، والتمييز بين مقياس الشارع والحي والمدينة عند تفسير النتائج."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["حرارة الهواء والسطح والرطوبة والرياح والإشعاع.","خصائص مواد السطح والغطاء الأرضي وارتفاعات المباني.","مواقع المحطات وارتفاع المجسات وظروف التعرض.","صور حرارية وخرائط عمرانية وبيانات سكانية مناسبة.","سلاسل زمنية تشمل النهار والليل ومواسم مختلفة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد النطاق الحضري والمقياس المكاني والهدف.","صنف الأسطح والأنماط العمرانية ومواقع الرصد.","حلل المتغيرات الجوية والسطحية معاً.","قارن المواقع الحضرية بمرجع مناسب مع ضبط الارتفاع والتوقيت.","قيم التدخلات بمؤشرات قابلة للقياس واذكر القيود."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"البنية الخضراء الحضرية","text":"قيم دور صف أشجار وحديقة صغيرة في ممر حضري وفق عوامل مناخية. استخدم سيناريو افتراضياً واضحاً، وبيّن الفرق بين القياس المرصود والاستنتاج المكاني."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قيم دور صف أشجار وحديقة صغيرة في ممر حضري وفق عوامل مناخية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار حرارة السطح مساوية لحرارة الهواء.","مقارنة محطات مختلفة التعرض أو الارتفاع دون ضبط.","تعميم قياس نقطة على كامل النسيج العمراني.","إغفال أثر الرطوبة والرياح والإشعاع في الإجهاد الحراري.","الحكم على تدخل دون خط أساس أو متابعة زمنية."]},{"type":"callout","text":"التقييم الحضري السليم يجمع بين القياسات الجوية وخصائص السطح والهندسة العمرانية والتعرض البشري، مع مراعاة اختلاف المقياس المكاني."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد علم المناخ الحضري على تفسير الفروق المحلية في الحرارة والتهوية وجودة الهواء، وتحويل الرصد المكاني إلى تدخلات تكيف قابلة للتقييم والتحسين."}]}'::jsonb,8440,55,'["شرح التفاعلات المناخية بين الغلاف الجوي والبيئة العمرانية","تحديد البيانات والمنهجيات المناسبة للرصد والتحليل الحضري","تقييم مخاطر الحرارة وخيارات التكيف على أسس علمية"]'::jsonb,'فيزياء المناخ الحضري والميزانية السطحية'),
('urban-blue-infrastructure','المسطحات المائية والتبريد الحضري','السعة الحرارية والتبخر والنسيم المحلي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تؤثر البحيرات والقنوات والمسطحات المائية في الحرارة والرطوبة والنسيم المحلي بسبب خصائصها الحرارية والتبخرية. يتوقف الأثر على حجم المسطح وعمقه والرياح والبيئة العمرانية."},{"type":"heading","text":"الآلية المناخية"},{"type":"text","text":"يتشكل المناخ الحضري من تفاعل الغلاف الجوي مع هندسة المباني وخصائص المواد والغطاء النباتي والماء ومصادر الحرارة البشرية. ويجب فصل حرارة السطح عن حرارة الهواء، والتمييز بين مقياس الشارع والحي والمدينة عند تفسير النتائج."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["حرارة الهواء والسطح والرطوبة والرياح والإشعاع.","خصائص مواد السطح والغطاء الأرضي وارتفاعات المباني.","مواقع المحطات وارتفاع المجسات وظروف التعرض.","صور حرارية وخرائط عمرانية وبيانات سكانية مناسبة.","سلاسل زمنية تشمل النهار والليل ومواسم مختلفة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد النطاق الحضري والمقياس المكاني والهدف.","صنف الأسطح والأنماط العمرانية ومواقع الرصد.","حلل المتغيرات الجوية والسطحية معاً.","قارن المواقع الحضرية بمرجع مناسب مع ضبط الارتفاع والتوقيت.","قيم التدخلات بمؤشرات قابلة للقياس واذكر القيود."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"المسطحات المائية والتبريد الحضري","text":"قارن أثر مسطح مائي نهاراً وليلاً في موقعين مختلفين. استخدم سيناريو افتراضياً واضحاً، وبيّن الفرق بين القياس المرصود والاستنتاج المكاني."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن أثر مسطح مائي نهاراً وليلاً في موقعين مختلفين."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار حرارة السطح مساوية لحرارة الهواء.","مقارنة محطات مختلفة التعرض أو الارتفاع دون ضبط.","تعميم قياس نقطة على كامل النسيج العمراني.","إغفال أثر الرطوبة والرياح والإشعاع في الإجهاد الحراري.","الحكم على تدخل دون خط أساس أو متابعة زمنية."]},{"type":"callout","text":"التقييم الحضري السليم يجمع بين القياسات الجوية وخصائص السطح والهندسة العمرانية والتعرض البشري، مع مراعاة اختلاف المقياس المكاني."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد علم المناخ الحضري على تفسير الفروق المحلية في الحرارة والتهوية وجودة الهواء، وتحويل الرصد المكاني إلى تدخلات تكيف قابلة للتقييم والتحسين."}]}'::jsonb,8450,55,'["شرح التفاعلات المناخية بين الغلاف الجوي والبيئة العمرانية","تحديد البيانات والمنهجيات المناسبة للرصد والتحليل الحضري","تقييم مخاطر الحرارة وخيارات التكيف على أسس علمية"]'::jsonb,'فيزياء المناخ الحضري والميزانية السطحية'),
('urban-boundary-layer','الطبقة الحدية فوق المدن','الخلط الحراري والاضطراب الحضري','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتأثر الطبقة الحدية الحضرية بالحرارة المخزنة والخشونة والانبعاثات والغطاء السحابي. قد يختلف ارتفاعها وبنيتها عن المناطق الريفية المجاورة، ما ينعكس على التهوية وجودة الهواء."},{"type":"heading","text":"الآلية المناخية"},{"type":"text","text":"يتشكل المناخ الحضري من تفاعل الغلاف الجوي مع هندسة المباني وخصائص المواد والغطاء النباتي والماء ومصادر الحرارة البشرية. ويجب فصل حرارة السطح عن حرارة الهواء، والتمييز بين مقياس الشارع والحي والمدينة عند تفسير النتائج."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["حرارة الهواء والسطح والرطوبة والرياح والإشعاع.","خصائص مواد السطح والغطاء الأرضي وارتفاعات المباني.","مواقع المحطات وارتفاع المجسات وظروف التعرض.","صور حرارية وخرائط عمرانية وبيانات سكانية مناسبة.","سلاسل زمنية تشمل النهار والليل ومواسم مختلفة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد النطاق الحضري والمقياس المكاني والهدف.","صنف الأسطح والأنماط العمرانية ومواقع الرصد.","حلل المتغيرات الجوية والسطحية معاً.","قارن المواقع الحضرية بمرجع مناسب مع ضبط الارتفاع والتوقيت.","قيم التدخلات بمؤشرات قابلة للقياس واذكر القيود."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الطبقة الحدية فوق المدن","text":"اشرح كيف يمكن لفقاعة حرارية حضرية أن تعدل نمو الطبقة الحدية. استخدم سيناريو افتراضياً واضحاً، وبيّن الفرق بين القياس المرصود والاستنتاج المكاني."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح كيف يمكن لفقاعة حرارية حضرية أن تعدل نمو الطبقة الحدية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار حرارة السطح مساوية لحرارة الهواء.","مقارنة محطات مختلفة التعرض أو الارتفاع دون ضبط.","تعميم قياس نقطة على كامل النسيج العمراني.","إغفال أثر الرطوبة والرياح والإشعاع في الإجهاد الحراري.","الحكم على تدخل دون خط أساس أو متابعة زمنية."]},{"type":"callout","text":"التقييم الحضري السليم يجمع بين القياسات الجوية وخصائص السطح والهندسة العمرانية والتعرض البشري، مع مراعاة اختلاف المقياس المكاني."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد علم المناخ الحضري على تفسير الفروق المحلية في الحرارة والتهوية وجودة الهواء، وتحويل الرصد المكاني إلى تدخلات تكيف قابلة للتقييم والتحسين."}]}'::jsonb,8460,55,'["شرح التفاعلات المناخية بين الغلاف الجوي والبيئة العمرانية","تحديد البيانات والمنهجيات المناسبة للرصد والتحليل الحضري","تقييم مخاطر الحرارة وخيارات التكيف على أسس علمية"]'::jsonb,'الرصد والتقييم والتكيف الحضري'),
