('urban-climate-modeling','نمذجة المناخ الحضري','تمثيل المباني والغطاء والميزانية السطحية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتراوح النماذج الحضرية بين معاملات سطحية مبسطة ونماذج تفصيلية لهندسة المباني وتبادل الطاقة. يتطلب الاختيار مواءمة الدقة والبيانات والهدف التشغيلي."},{"type":"heading","text":"الآلية المناخية"},{"type":"text","text":"يتشكل المناخ الحضري من تفاعل الغلاف الجوي مع هندسة المباني وخصائص المواد والغطاء النباتي والماء ومصادر الحرارة البشرية. ويجب فصل حرارة السطح عن حرارة الهواء، والتمييز بين مقياس الشارع والحي والمدينة عند تفسير النتائج."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["حرارة الهواء والسطح والرطوبة والرياح والإشعاع.","خصائص مواد السطح والغطاء الأرضي وارتفاعات المباني.","مواقع المحطات وارتفاع المجسات وظروف التعرض.","صور حرارية وخرائط عمرانية وبيانات سكانية مناسبة.","سلاسل زمنية تشمل النهار والليل ومواسم مختلفة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد النطاق الحضري والمقياس المكاني والهدف.","صنف الأسطح والأنماط العمرانية ومواقع الرصد.","حلل المتغيرات الجوية والسطحية معاً.","قارن المواقع الحضرية بمرجع مناسب مع ضبط الارتفاع والتوقيت.","قيم التدخلات بمؤشرات قابلة للقياس واذكر القيود."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"نمذجة المناخ الحضري","text":"حدد مستوى تمثيل حضري مناسباً لدراسة حي كامل مقابل شارع واحد. استخدم سيناريو افتراضياً واضحاً، وبيّن الفرق بين القياس المرصود والاستنتاج المكاني."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد مستوى تمثيل حضري مناسباً لدراسة حي كامل مقابل شارع واحد."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار حرارة السطح مساوية لحرارة الهواء.","مقارنة محطات مختلفة التعرض أو الارتفاع دون ضبط.","تعميم قياس نقطة على كامل النسيج العمراني.","إغفال أثر الرطوبة والرياح والإشعاع في الإجهاد الحراري.","الحكم على تدخل دون خط أساس أو متابعة زمنية."]},{"type":"callout","text":"التقييم الحضري السليم يجمع بين القياسات الجوية وخصائص السطح والهندسة العمرانية والتعرض البشري، مع مراعاة اختلاف المقياس المكاني."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد علم المناخ الحضري على تفسير الفروق المحلية في الحرارة والتهوية وجودة الهواء، وتحويل الرصد المكاني إلى تدخلات تكيف قابلة للتقييم والتحسين."}]}'::jsonb,8520,55,'["شرح التفاعلات المناخية بين الغلاف الجوي والبيئة العمرانية","تحديد البيانات والمنهجيات المناسبة للرصد والتحليل الحضري","تقييم مخاطر الحرارة وخيارات التكيف على أسس علمية"]'::jsonb,'الرصد والتقييم والتكيف الحضري'),
('urban-cooling-interventions','تقييم تدخلات تخفيف الحرارة','الأسطح الباردة والتشجير والظل','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تشمل التدخلات الأسطح العاكسة والتشجير والظل والتهوية وتغيير المواد. ينبغي تقييم أثرها على حرارة الهواء والسطح والراحة والطاقة والمياه، مع مراعاة التوزيع العادل للفوائد."},{"type":"heading","text":"الآلية المناخية"},{"type":"text","text":"يتشكل المناخ الحضري من تفاعل الغلاف الجوي مع هندسة المباني وخصائص المواد والغطاء النباتي والماء ومصادر الحرارة البشرية. ويجب فصل حرارة السطح عن حرارة الهواء، والتمييز بين مقياس الشارع والحي والمدينة عند تفسير النتائج."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["حرارة الهواء والسطح والرطوبة والرياح والإشعاع.","خصائص مواد السطح والغطاء الأرضي وارتفاعات المباني.","مواقع المحطات وارتفاع المجسات وظروف التعرض.","صور حرارية وخرائط عمرانية وبيانات سكانية مناسبة.","سلاسل زمنية تشمل النهار والليل ومواسم مختلفة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد النطاق الحضري والمقياس المكاني والهدف.","صنف الأسطح والأنماط العمرانية ومواقع الرصد.","حلل المتغيرات الجوية والسطحية معاً.","قارن المواقع الحضرية بمرجع مناسب مع ضبط الارتفاع والتوقيت.","قيم التدخلات بمؤشرات قابلة للقياس واذكر القيود."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تقييم تدخلات تخفيف الحرارة","text":"أنشئ إطار مقارنة متعدد المعايير بين تدخلين حضريين. استخدم سيناريو افتراضياً واضحاً، وبيّن الفرق بين القياس المرصود والاستنتاج المكاني."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"أنشئ إطار مقارنة متعدد المعايير بين تدخلين حضريين."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار حرارة السطح مساوية لحرارة الهواء.","مقارنة محطات مختلفة التعرض أو الارتفاع دون ضبط.","تعميم قياس نقطة على كامل النسيج العمراني.","إغفال أثر الرطوبة والرياح والإشعاع في الإجهاد الحراري.","الحكم على تدخل دون خط أساس أو متابعة زمنية."]},{"type":"callout","text":"التقييم الحضري السليم يجمع بين القياسات الجوية وخصائص السطح والهندسة العمرانية والتعرض البشري، مع مراعاة اختلاف المقياس المكاني."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد علم المناخ الحضري على تفسير الفروق المحلية في الحرارة والتهوية وجودة الهواء، وتحويل الرصد المكاني إلى تدخلات تكيف قابلة للتقييم والتحسين."}]}'::jsonb,8530,55,'["شرح التفاعلات المناخية بين الغلاف الجوي والبيئة العمرانية","تحديد البيانات والمنهجيات المناسبة للرصد والتحليل الحضري","تقييم مخاطر الحرارة وخيارات التكيف على أسس علمية"]'::jsonb,'الرصد والتقييم والتكيف الحضري'),
('urban-climate-monitoring-network','شبكة مراقبة المناخ الحضري','تمثيل الأحياء والارتفاعات وأنواع السطح','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تحتاج الشبكة إلى محطات تمثل أنماطاً عمرانية مختلفة ومناطق مرجعية خارج المدينة، مع توحيد مواصفات التركيب والمعايرة والاتصال. ويمكن دمج المستشعرات الثابتة والمتنقلة."},{"type":"heading","text":"الآلية المناخية"},{"type":"text","text":"يتشكل المناخ الحضري من تفاعل الغلاف الجوي مع هندسة المباني وخصائص المواد والغطاء النباتي والماء ومصادر الحرارة البشرية. ويجب فصل حرارة السطح عن حرارة الهواء، والتمييز بين مقياس الشارع والحي والمدينة عند تفسير النتائج."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["حرارة الهواء والسطح والرطوبة والرياح والإشعاع.","خصائص مواد السطح والغطاء الأرضي وارتفاعات المباني.","مواقع المحطات وارتفاع المجسات وظروف التعرض.","صور حرارية وخرائط عمرانية وبيانات سكانية مناسبة.","سلاسل زمنية تشمل النهار والليل ومواسم مختلفة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد النطاق الحضري والمقياس المكاني والهدف.","صنف الأسطح والأنماط العمرانية ومواقع الرصد.","حلل المتغيرات الجوية والسطحية معاً.","قارن المواقع الحضرية بمرجع مناسب مع ضبط الارتفاع والتوقيت.","قيم التدخلات بمؤشرات قابلة للقياس واذكر القيود."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"شبكة مراقبة المناخ الحضري","text":"صمم توزيعاً مفاهيمياً لمحطات في مركز المدينة والضواحي والريف المرجعي. استخدم سيناريو افتراضياً واضحاً، وبيّن الفرق بين القياس المرصود والاستنتاج المكاني."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم توزيعاً مفاهيمياً لمحطات في مركز المدينة والضواحي والريف المرجعي."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار حرارة السطح مساوية لحرارة الهواء.","مقارنة محطات مختلفة التعرض أو الارتفاع دون ضبط.","تعميم قياس نقطة على كامل النسيج العمراني.","إغفال أثر الرطوبة والرياح والإشعاع في الإجهاد الحراري.","الحكم على تدخل دون خط أساس أو متابعة زمنية."]},{"type":"callout","text":"التقييم الحضري السليم يجمع بين القياسات الجوية وخصائص السطح والهندسة العمرانية والتعرض البشري، مع مراعاة اختلاف المقياس المكاني."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد علم المناخ الحضري على تفسير الفروق المحلية في الحرارة والتهوية وجودة الهواء، وتحويل الرصد المكاني إلى تدخلات تكيف قابلة للتقييم والتحسين."}]}'::jsonb,8540,55,'["شرح التفاعلات المناخية بين الغلاف الجوي والبيئة العمرانية","تحديد البيانات والمنهجيات المناسبة للرصد والتحليل الحضري","تقييم مخاطر الحرارة وخيارات التكيف على أسس علمية"]'::jsonb,'الرصد والتقييم والتكيف الحضري'),
('urban-climate-adaptation-planning','التكيف المناخي الحضري القائم على الأدلة','خرائط التعرض والهشاشة والخيارات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يربط التخطيط المناخي الحضري خرائط الحرارة والتعرض السكاني والبنية التحتية والغطاء الأرضي بخيارات التكيف. تتطلب الأولويات بيانات مكانية موثوقة ومشاركة الجهات المحلية ومتابعة مؤشرات الأداء."},{"type":"heading","text":"الآلية المناخية"},{"type":"text","text":"يتشكل المناخ الحضري من تفاعل الغلاف الجوي مع هندسة المباني وخصائص المواد والغطاء النباتي والماء ومصادر الحرارة البشرية. ويجب فصل حرارة السطح عن حرارة الهواء، والتمييز بين مقياس الشارع والحي والمدينة عند تفسير النتائج."},{"type":"heading","text":"البيانات المطلوبة"},{"type":"list","items":["حرارة الهواء والسطح والرطوبة والرياح والإشعاع.","خصائص مواد السطح والغطاء الأرضي وارتفاعات المباني.","مواقع المحطات وارتفاع المجسات وظروف التعرض.","صور حرارية وخرائط عمرانية وبيانات سكانية مناسبة.","سلاسل زمنية تشمل النهار والليل ومواسم مختلفة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد النطاق الحضري والمقياس المكاني والهدف.","صنف الأسطح والأنماط العمرانية ومواقع الرصد.","حلل المتغيرات الجوية والسطحية معاً.","قارن المواقع الحضرية بمرجع مناسب مع ضبط الارتفاع والتوقيت.","قيم التدخلات بمؤشرات قابلة للقياس واذكر القيود."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"التكيف المناخي الحضري القائم على الأدلة","text":"ضع سلسلة عمل لتحويل خريطة حرارة حضرية إلى أولويات تدخل قابلة للتقييم. استخدم سيناريو افتراضياً واضحاً، وبيّن الفرق بين القياس المرصود والاستنتاج المكاني."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ضع سلسلة عمل لتحويل خريطة حرارة حضرية إلى أولويات تدخل قابلة للتقييم."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار حرارة السطح مساوية لحرارة الهواء.","مقارنة محطات مختلفة التعرض أو الارتفاع دون ضبط.","تعميم قياس نقطة على كامل النسيج العمراني.","إغفال أثر الرطوبة والرياح والإشعاع في الإجهاد الحراري.","الحكم على تدخل دون خط أساس أو متابعة زمنية."]},{"type":"callout","text":"التقييم الحضري السليم يجمع بين القياسات الجوية وخصائص السطح والهندسة العمرانية والتعرض البشري، مع مراعاة اختلاف المقياس المكاني."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد علم المناخ الحضري على تفسير الفروق المحلية في الحرارة والتهوية وجودة الهواء، وتحويل الرصد المكاني إلى تدخلات تكيف قابلة للتقييم والتحسين."}]}'::jsonb,8550,55,'["شرح التفاعلات المناخية بين الغلاف الجوي والبيئة العمرانية","تحديد البيانات والمنهجيات المناسبة للرصد والتحليل الحضري","تقييم مخاطر الحرارة وخيارات التكيف على أسس علمية"]'::jsonb,'الرصد والتقييم والتكيف الحضري')
)
insert into public.academy_lessons(course_id,chapter_id,unit_id,chapter_title,unit_title,slug,title,summary,content,published,sort_order,estimated_minutes,learning_objectives,level)
select c.id,ch.id,case when d.unit_title='فيزياء المناخ الحضري والميزانية السطحية' then u1.id else u2.id end,'المناخ الحضري والجزيرة الحرارية والتكيف',d.unit_title,d.slug,d.title,d.summary,d.content,false,d.ord,d.mins,d.objectives,'advanced'
from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,level=excluded.level;